  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --bg-elevated: #111111;
      --bg-card: #1A1A1A;
      --bg-card-hover: #222222;
      --text: #FFFFFF;
      --text-secondary: #999999;
      --text-tertiary: #666666;
      --accent: #2979FF;
      --accent-hover: #448AFF;
      --accent-dim: rgba(41, 121, 255, 0.15);
      --border: #222222;
      --border-light: #333333;
      --radius: 8px;
      --radius-lg: 16px;
      --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      --max-width: 1320px;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    .container {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 40px;
    }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      background: rgba(10, 10, 10, 0.85);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid rgba(255,255,255,0.06);
      transition: var(--transition);
    }
    .nav-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 40px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }
    .nav-logo {
      font-size: 1.5rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      color: var(--text);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .nav-logo span { color: var(--accent); }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 0.875rem;
      font-weight: 500;
      letter-spacing: 0.01em;
      transition: var(--transition);
    }
    .nav-links a:hover { color: var(--text); }

    /* Language Selector */
    .lang-selector {
      position: relative;
      margin-left: 16px;
    }
    .lang-btn {
      display: flex;
      align-items: center;
      gap: 6px;
      background: none;
      border: 1px solid var(--border-light);
      color: var(--text-secondary);
      padding: 8px 14px;
      border-radius: var(--radius);
      font-size: 0.8125rem;
      font-family: inherit;
      cursor: pointer;
      transition: var(--transition);
    }
    .lang-btn:hover { color: var(--text); border-color: var(--text-tertiary); }
    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg-elevated);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      min-width: 180px;
      padding: 6px;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: var(--transition);
      z-index: 100;
    }
    .lang-dropdown.active { opacity: 1; visibility: visible; transform: translateY(0); }
    .lang-dropdown button {
      display: block;
      width: 100%;
      text-align: left;
      padding: 10px 14px;
      background: none;
      border: none;
      color: var(--text-secondary);
      font-size: 0.8125rem;
      font-family: inherit;
      cursor: pointer;
      border-radius: 6px;
      transition: var(--transition);
    }
    .lang-dropdown button:hover { background: var(--bg-card); color: var(--text); }
    .lang-dropdown button.active { color: var(--accent); }

    .nav-toggle {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      background: none;
      border: none;
      padding: 4px;
    }
    .nav-toggle span {
      width: 24px; height: 2px;
      background: var(--text);
      transition: var(--transition);
    }

    /* Hero Section */
    .hero {
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      justify-content: center;
      padding-top: 72px;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -50%; left: -50%;
      width: 200%; height: 200%;
      background: radial-gradient(ellipse at 30% 50%, rgba(41,121,255,0.06) 0%, transparent 50%),
                  radial-gradient(ellipse at 70% 30%, rgba(41,121,255,0.03) 0%, transparent 40%);
      pointer-events: none;
    }
    .hero-inner {
      position: relative;
      z-index: 1;
      padding: 80px 0;
    }
    .hero-slides {
      position: relative;
      min-height: 420px;
    }
    .hero-slide {
      position: absolute;
      top: 0; left: 0; right: 0;
      opacity: 0;
      transform: translateY(20px);
      transition: opacity 0.6s ease, transform 0.6s ease;
      pointer-events: none;
    }
    .hero-slide.active {
      opacity: 1;
      transform: translateY(0);
      pointer-events: auto;
    }
    .hero-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 24px;
      padding: 6px 12px;
      background: var(--accent-dim);
      border-radius: 100px;
    }
    .hero-slide h1 {
      font-size: clamp(2.5rem, 5vw, 4.5rem);
      font-weight: 800;
      line-height: 1.08;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
      max-width: 900px;
    }
    .hero-slide p {
      font-size: 1.125rem;
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.7;
      margin-bottom: 36px;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      border-radius: var(--radius);
      font-size: 0.9375rem;
      font-weight: 600;
      font-family: inherit;
      text-decoration: none;
      cursor: pointer;
      border: none;
      transition: var(--transition);
      letter-spacing: 0.01em;
    }
    .btn-primary {
      background: var(--accent);
      color: #fff;
    }
    .btn-primary:hover { background: var(--accent-hover); }
    .btn-outline {
      background: transparent;
      color: var(--text);
      border: 1px solid var(--border-light);
    }
    .btn-outline:hover { border-color: var(--text-tertiary); background: var(--bg-card); }

    .hero-dots {
      display: flex;
      gap: 8px;
      margin-top: 48px;
    }
    .hero-dot {
      width: 32px; height: 3px;
      background: var(--border-light);
      border: none;
      cursor: pointer;
      transition: var(--transition);
      border-radius: 2px;
    }
    .hero-dot.active { background: var(--accent); width: 48px; }

    /* Section Shared */
    .section {
      padding: 120px 0;
      position: relative;
    }
    .section-label {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 16px;
    }
    .section-title {
      font-size: clamp(2rem, 4vw, 3.5rem);
      font-weight: 800;
      line-height: 1.12;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
      max-width: 800px;
    }
    .section-subtitle {
      font-size: 1.125rem;
      color: var(--text-secondary);
      max-width: 600px;
      line-height: 1.7;
      margin-bottom: 56px;
    }

    /* Team Section */
    .team-section { background: var(--bg-elevated); }
    .region-tabs {
      display: flex;
      gap: 8px;
      margin-bottom: 48px;
      flex-wrap: wrap;
    }
    .region-tab {
      padding: 10px 22px;
      border-radius: 100px;
      background: transparent;
      border: 1px solid var(--border-light);
      color: var(--text-secondary);
      font-size: 0.875rem;
      font-weight: 500;
      font-family: inherit;
      cursor: pointer;
      transition: var(--transition);
    }
    .region-tab.active {
      background: var(--accent);
      border-color: var(--accent);
      color: #fff;
    }
    .region-tab:hover:not(.active) {
      border-color: var(--text-tertiary);
      color: var(--text);
    }

    .team-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 24px;
      transition: var(--transition);
    }
    .team-card {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--border);
      transition: var(--transition);
      display: flex;
      flex-direction: column;
    }
    .team-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
    .team-card-photo {
      width: 64px; height: 64px;
      border-radius: 50%;
      background: var(--border-light);
      margin-bottom: 20px;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      color: var(--text-tertiary);
    }
    .team-card-photo img { width: 100%; height: 100%; object-fit: cover; }
    .team-card blockquote {
      font-size: 0.9375rem;
      line-height: 1.65;
      color: var(--text-secondary);
      margin-bottom: 24px;
      flex: 1;
      font-style: italic;
    }
    .team-card-name {
      font-weight: 600;
      font-size: 1rem;
      color: var(--text);
    }
    .team-card-role {
      font-size: 0.8125rem;
      color: var(--text-tertiary);
      margin-bottom: 2px;
    }
    .team-card-office {
      font-size: 0.8125rem;
      color: var(--accent);
      margin-bottom: 16px;
    }
    .team-card-cta {
      font-size: 0.8125rem;
      color: var(--text-secondary);
      text-decoration: none;
      font-weight: 500;
      transition: var(--transition);
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }
    .team-card-cta:hover { color: var(--accent); }

    /* Work Section */
    .work-scroll {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding-bottom: 16px;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: thin;
      scrollbar-color: var(--border-light) transparent;
    }
    .work-scroll::-webkit-scrollbar { height: 6px; }
    .work-scroll::-webkit-scrollbar-track { background: transparent; }
    .work-scroll::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }

    .work-card {
      min-width: 380px;
      max-width: 420px;
      flex-shrink: 0;
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      overflow: hidden;
      transition: var(--transition);
      cursor: pointer;
    }
    .work-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
    .work-card-img {
      width: 100%; height: 220px;
      background: var(--border-light);
      position: relative;
      overflow: hidden;
    }
    .work-card-img img {
      width: 100%; height: 100%;
      object-fit: cover;
    }
    .work-card-body {
      padding: 24px;
    }
    .work-card-client {
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.06em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 8px;
    }
    .work-card-title {
      font-size: 1.125rem;
      font-weight: 700;
      line-height: 1.3;
      margin-bottom: 12px;
      color: var(--text);
    }
    .work-card-quote {
      font-size: 0.8125rem;
      color: var(--text-tertiary);
      line-height: 1.6;
      font-style: italic;
    }
    .work-nav {
      display: flex;
      gap: 12px;
      margin-top: 32px;
    }
    .work-nav-btn {
      width: 44px; height: 44px;
      border-radius: 50%;
      background: var(--bg-card);
      border: 1px solid var(--border-light);
      color: var(--text);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: var(--transition);
      font-size: 1.125rem;
    }
    .work-nav-btn:hover { background: var(--bg-card-hover); border-color: var(--text-tertiary); }

    /* CTA Banner */
    .cta-banner {
      background: linear-gradient(135deg, #0D1B3E 0%, #0A1628 50%, #0D1B3E 100%);
      border-top: 1px solid rgba(41,121,255,0.15);
      border-bottom: 1px solid rgba(41,121,255,0.15);
    }
    .cta-banner .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 48px;
      flex-wrap: wrap;
    }
    .cta-banner h2 {
      font-size: 1.75rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 12px;
    }
    .cta-banner p {
      color: var(--text-secondary);
      max-width: 560px;
      line-height: 1.7;
    }

    /* How We Work */
    .how-we-work {
      background: var(--bg);
    }
    .how-we-work .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .how-we-work-visual {
      aspect-ratio: 4/3;
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 6rem;
      color: var(--border-light);
    }
    .how-we-work h2 {
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      margin-bottom: 20px;
    }
    .how-we-work p {
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 28px;
      font-size: 1.0625rem;
    }

    /* Insights */
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }
    .insight-card {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: 28px;
      border: 1px solid var(--border);
      transition: var(--transition);
      cursor: pointer;
      display: flex;
      flex-direction: column;
    }
    .insight-card:hover { border-color: var(--border-light); background: var(--bg-card-hover); }
    .insight-type {
      font-size: 0.6875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
      margin-bottom: 12px;
    }
    .insight-card h3 {
      font-size: 1.0625rem;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 20px;
      flex: 1;
    }
    .insight-card .cta-link {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 0.875rem;
      font-weight: 500;
      transition: var(--transition);
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }
    .insight-card:hover .cta-link { color: var(--accent); }

    /* Principles */
    .principles-section { background: var(--bg-elevated); }
    .principles-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }
    .principle-card {
      background: var(--bg-card);
      border-radius: var(--radius-lg);
      padding: 36px;
      border: 1px solid var(--border);
      transition: var(--transition);
    }
    .principle-card:hover { border-color: var(--border-light); }
    .principle-number {
      font-size: 3rem;
      font-weight: 900;
      color: var(--bg-elevated);
      -webkit-text-stroke: 1px var(--border-light);
      line-height: 1;
      margin-bottom: 16px;
    }
    .principle-card h3 {
      font-size: 1.125rem;
      font-weight: 700;
      margin-bottom: 12px;
    }
    .principle-card p {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.65;
    }

    /* Footer */
    .footer {
      padding: 80px 0 40px;
      border-top: 1px solid var(--border);
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      padding-bottom: 48px;
      border-bottom: 1px solid var(--border);
      margin-bottom: 40px;
    }
    .footer-cta h3 {
      font-size: 1.25rem;
      font-weight: 700;
      margin-bottom: 8px;
      line-height: 1.4;
    }
    .footer-cta p {
      color: var(--text-secondary);
      margin-bottom: 20px;
      line-height: 1.6;
      font-size: 0.9375rem;
    }
    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }
    .footer-links {
      display: flex;
      gap: 20px;
      list-style: none;
      flex-wrap: wrap;
    }
    .footer-links a {
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 0.8125rem;
      transition: var(--transition);
    }
    .footer-links a:hover { color: var(--text); }
    .footer-legal {
      font-size: 0.8125rem;
      color: var(--text-tertiary);
    }

    /* Cookie Consent */
    .cookie-banner {
      position: fixed;
      bottom: 24px; left: 24px; right: 24px;
      max-width: 480px;
      background: var(--bg-elevated);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 24px;
      z-index: 999;
      box-shadow: 0 24px 48px rgba(0,0,0,0.5);
      transform: translateY(calc(100% + 32px));
      opacity: 0;
      transition: var(--transition);
      pointer-events: none;
    }
    .cookie-banner.visible {
      transform: translateY(0);
      opacity: 1;
      pointer-events: auto;
    }
    .cookie-banner p {
      font-size: 0.8125rem;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-bottom: 16px;
    }
    .cookie-banner p strong { color: var(--text); }
    .cookie-actions {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }
    .cookie-actions .btn {
      font-size: 0.8125rem;
      padding: 10px 18px;
    }

    /* Animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate-in {
      animation: fadeInUp 0.6s ease forwards;
    }

    /* Mobile */
    @media (max-width: 768px) {
      .container { padding: 0 20px; }
      .nav-inner { padding: 0 20px; }
      .nav-links { display: none; }
      .nav-links.open {
        display: flex;
        flex-direction: column;
